function _base64ToBytes(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

const BYTES_PER_ROW = Math.ceil(GRID_W / 8);
const _packed = _base64ToBytes(MASK_B64);

/** true = open/walkable tile, false = wall. gx/gy are integer tile coords. */
export function isOpenTile(gx, gy) {
  if (gx < 0 || gx >= GRID_W || gy < 0 || gy >= GRID_H) return false;
  const byteIndex = gy * BYTES_PER_ROW + (gx >> 3);
  const bitIndex = 7 - (gx & 7); // packbits is MSB-first
  return ((_packed[byteIndex] >> bitIndex) & 1) === 1;
}

function worldToTile(x, y) {
  return { gx: Math.floor(x / TILE_SIZE), gy: Math.floor(y / TILE_SIZE) };
}

// ── Collision / movement ──────────────────────────────────────────────────────
// Checks the tiles under a circle of the given radius — samples the four
// cardinal edge points plus center, which is enough to catch wall contact
// for a mostly-round hitbox without a full per-pixel sweep every frame.
export function canMoveTo(x, y, radius = 22) {
  if (x - radius < 0 || x + radius > MAP_W ||
      y - radius < 0 || y + radius > MAP_H) return false;

  const points = [
    [x, y],
    [x - radius, y], [x + radius, y],
    [x, y - radius], [x, y + radius],
  ];
  for (const [px, py] of points) {
    const { gx, gy } = worldToTile(px, py);
    if (!isOpenTile(gx, gy)) return false;
  }
  return true;
}

// ── Player safe-spawn ──────────────────────────────────────────────────────────
// Returns the PNG-marked spawn point. Falls back to a nearby open tile search
// if that exact point is ever somehow blocked (shouldn't happen — verified at
// build time — but keeps this safe against future mask edits).
export function findSafeSpawnPosition(radius = 22, playerX, playerY, safeRadius = 350) {
  if (canMoveTo(SPAWN_WORLD_X, SPAWN_WORLD_Y, radius)) {
    if (playerX === undefined || Math.hypot(SPAWN_WORLD_X - playerX, SPAWN_WORLD_Y - playerY) >= safeRadius) {
      return { x: SPAWN_WORLD_X, y: SPAWN_WORLD_Y };
    }
  }
  // Fallback: spiral search outward from the marked spawn for any open tile
  const { gx: sgx, gy: sgy } = worldToTile(SPAWN_WORLD_X, SPAWN_WORLD_Y);
  for (let r = 1; r < 40; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const gx = sgx + dx, gy = sgy + dy;
        if (!isOpenTile(gx, gy)) continue;
        const wx = (gx + 0.5) * TILE_SIZE, wy = (gy + 0.5) * TILE_SIZE;
        if (canMoveTo(wx, wy, radius)) return { x: wx, y: wy };
      }
    }
  }
  return { x: SPAWN_WORLD_X, y: SPAWN_WORLD_Y }; // should never reach here
}

// ── Mob spawn anywhere open (no overlap with existing mobs) ───────────────────
// Not wired to any spawn system yet (phase 2 scope is map geometry only) but
// provided now so mobs.js's shim can eventually call a real implementation
// instead of the flat-map fallback in map.js.
export function findOpenSpawnPosition(radius, existingMobs, tries = 60) {
  for (let i = 0; i < tries; i++) {
    const gx = Math.floor(Math.random() * GRID_W);
    const gy = Math.floor(Math.random() * GRID_H);
    const x = (gx + 0.5) * TILE_SIZE, y = (gy + 0.5) * TILE_SIZE;
    if (!canMoveTo(x, y, radius)) continue;
    let clear = true;
    if (existingMobs) {
      for (const m of existingMobs) {
        if (m.dead) continue;
        if (Math.hypot(x - m.x, y - m.y) < radius + m.radius + 12) { clear = false; break; }
      }
    }
    if (clear) return { x, y };
  }
  return null;
}

// ── World-space map drawing ───────────────────────────────────────────────────
// Draws tile-by-tile within the camera viewport only (not the whole grid every
// frame) — walls and floor as flat fills; no per-tile borders/bumps drawn
// individually since that would be far too slow with a large viewport. The
// PNG's bumpy silhouette comes through naturally from the tile boundaries
// once zoomed to actual play scale.
export function drawMap(ctx, cameraX, cameraY, canvasW, canvasH, zoomV = 1) {
  const hw = canvasW / 2, hh = canvasH / 2;
  const wx2sx = wx => (wx - cameraX) * zoomV + hw;
  const wy2sy = wy => (wy - cameraY) * zoomV + hh;

  // Dark outside (beyond map bounds)
  ctx.fillStyle = '#120c04';
  ctx.fillRect(0, 0, canvasW, canvasH);

  // Visible tile range (with 1 tile margin so edge tiles aren't clipped early)
  const worldLeft   = cameraX - hw / zoomV;
  const worldRight  = cameraX + hw / zoomV;
  const worldTop    = cameraY - hh / zoomV;
  const worldBottom = cameraY + hh / zoomV;

  const gx0 = Math.max(0, Math.floor(worldLeft / TILE_SIZE) - 1);
  const gx1 = Math.min(GRID_W - 1, Math.ceil(worldRight / TILE_SIZE) + 1);
  const gy0 = Math.max(0, Math.floor(worldTop / TILE_SIZE) - 1);
  const gy1 = Math.min(GRID_H - 1, Math.ceil(worldBottom / TILE_SIZE) + 1);

  const tileScreenSize = TILE_SIZE * zoomV;

  for (let gy = gy0; gy <= gy1; gy++) {
    for (let gx = gx0; gx <= gx1; gx++) {
      const open = isOpenTile(gx, gy);
      ctx.fillStyle = open ? FLOOR_COLOR : MAP_WALL_COLOR;
      const sx = wx2sx(gx * TILE_SIZE);
      const sy = wy2sy(gy * TILE_SIZE);
      // Slight overdraw (+1px) to avoid hairline seams between tiles from
      // sub-pixel rounding at non-integer zoom levels.
      ctx.fillRect(sx, sy, tileScreenSize + 1, tileScreenSize + 1);
    }
  }

  // Border walls around the whole map
  const wt = Math.max(3, 8 * zoomV);
  const mapLeft = wx2sx(0), mapTop = wy2sy(0);
  const mapRight = wx2sx(MAP_W), mapBottom = wy2sy(MAP_H);
  ctx.fillStyle = MAP_WALL_COLOR;
  ctx.fillRect(mapLeft - wt, mapTop - wt, (mapRight - mapLeft) + wt * 2, wt);
  ctx.fillRect(mapLeft - wt, mapBottom, (mapRight - mapLeft) + wt * 2, wt);
  ctx.fillRect(mapLeft - wt, mapTop - wt, wt, (mapBottom - mapTop) + wt * 2);
  ctx.fillRect(mapRight, mapTop - wt, wt, (mapBottom - mapTop) + wt * 2);
}
